            const __m512d _v7_im = _mm512_permutex2var_pd(_u5_im, _tp_idx_hi, _u7_im);
            _mm512_storeu_pd(&rio_im[(b+0)*row_stride + 0], _mm512_shuffle_f64x2(_v0_im, _v4_im, 0x44));
            _mm512_storeu_pd(&rio_im[(b+1)*row_stride + 0], _mm512_shuffle_f64x2(_v1_im, _v5_im, 0x44));
            _mm512_storeu_pd(&rio_im[(b+2)*row_stride + 0], _mm512_shuffle_f64x2(_v2_im, _v6_im, 0x44));
